                        `type`="text"),
                    list(
                        `name`="formula_ref", 
                        `title`="Primary Formula", 
                        `type`="text"))))
            self$add(jmvcore::Image$new(
                options=options,
                name="esPlot",
                title="Effect Size Forest Plot",
                width=650,
                height=450,
                renderFun=".renderESPlot",
                visible="(run_analysis && show_es_plot)",
                requiresData=TRUE,
