                    "show_es_plot",
                    "plot_width",
                    "plot_height")))
            self$add(jmvcore::Preformatted$new(
                options=options,
                name="text",
                title="Analysis Summary",
                visible=FALSE,
                clearWith=list(
                    "mode",
                    "dep_vars_cs",
