                    "show_categorical_es",
                    "cat_var1",
                    "cat_var2",
                    "calc_from_test_stat")))}))

effectSizeBase <- if (requireNamespace("jmvcore", quietly=TRUE)) R6::R6Class(
    "effectSizeBase",
    inherit = jmvcore::Analysis,
    public = list(
        initialize = function(options, data=NULL, datasetId="", analysisId="", revision=0) {
            super$initialize(
                package = "BSS",
                name = "effectSize",
                version = c(0,0,1),
                options = options,
                results = effectSizeResults$new(options=options),
                data = data,
                datasetId = datasetId,
                analysisId = analysisId,
                revision = revision,
                pause = NULL,
                completeWhenFilled = FALSE,
                requiresMissings = FALSE,
                weightsSupport = 'auto')
        }))

#' Effect Size Calculation
#'
#' 
#' @param data .
#' @param mode .
#' @param dep_vars_cs .
#' @param indep_vars_cs .
#' @param cov .
#' @param dep_vars_long .
#' @param indep_vars_long .
#' @param cov_long .
#' @param subject_id_var .
#' @param time_var .
#' @param wave_vars .
#' @param long_format .
#' @param include_interactions .
#' @param run_analysis .
#' @param es_method .
#' @param show_cles .
#' @param reference_group .
#' @param es_method_long .
#' @param show_cles_long .
#' @param reference_group_long .
#' @param use_glm .
#' @param es_glm .
#' @param ci_method .
#' @param n_bootstrap .
#' @param ci_level .
#' @param show_conversions .
#' @param benchmark_standard .
#' @param show_es_plot .
#' @param plot_width .
#' @param plot_height .
#' @param show_categorical_es .
#' @param cat_var1 .
#' @param cat_var2 .
#' @param calc_from_test_stat .
#' @param stat_type .
#' @param stat_val .
#' @param stat_df1 .
#' @param stat_df2 .
#' @param stat_n .
#' @return A results object containing:
#' \tabular{llllll}{
#'   \code{results$analysisInfo} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$ameBenchmark} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$effectSizeTable} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$effectSizeTableLongBetween} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$clesTable} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$clesLongTable} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$conversionTable} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$categoricalTable} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$directCalcTable} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$esPlot} \tab \tab \tab \tab \tab an image \cr
#'   \code{results$text} \tab \tab \tab \tab \tab a preformatted \cr
#' }
#'
#' Tables can be converted to data frames with \code{asDF} or \code{\link{as.data.frame}}. For example:
#'
#' \code{results$effectSizeTable$asDF}
#'
#' \code{as.data.frame(results$effectSizeTable)}
#'
#' @export
effectSize <- function(
    data,
    mode = "cross_sectional",
    dep_vars_cs = NULL,
    indep_vars_cs = NULL,
    cov = NULL,
    dep_vars_long = NULL,
    indep_vars_long = NULL,
    cov_long = NULL,
    subject_id_var = NULL,
    time_var = NULL,
    wave_vars = NULL,
    long_format = "wide",
    include_interactions = FALSE,
    run_analysis = FALSE,
    es_method = "cohens_d",
    show_cles = FALSE,
    reference_group = "",
    es_method_long = "cohens_dz",
    show_cles_long = FALSE,
    reference_group_long = "",
    use_glm = FALSE,
    es_glm = "glm_gaussian",
    ci_method = "analytical",
    n_bootstrap = 1000,
    ci_level = "ci_95",
    show_conversions = FALSE,
    benchmark_standard = "cohen",
    show_es_plot = FALSE,
    plot_width = 650,
    plot_height = 450,
    show_categorical_es = FALSE,
    cat_var1 = NULL,
    cat_var2 = NULL,
    calc_from_test_stat = FALSE,
    stat_type = "stat_t",
    stat_val = 2.5,
    stat_df1 = 30,
    stat_df2 = 60,
    stat_n = 60) {

    if ( ! requireNamespace("jmvcore", quietly=TRUE))
        stop("effectSize requires jmvcore to be installed (restart may be required)")

    if ( ! missing(dep_vars_cs)) dep_vars_cs <- jmvcore::resolveQuo(jmvcore::enquo(dep_vars_cs))
    if ( ! missing(indep_vars_cs)) indep_vars_cs <- jmvcore::resolveQuo(jmvcore::enquo(indep_vars_cs))
    if ( ! missing(cov)) cov <- jmvcore::resolveQuo(jmvcore::enquo(cov))
    if ( ! missing(dep_vars_long)) dep_vars_long <- jmvcore::resolveQuo(jmvcore::enquo(dep_vars_long))
    if ( ! missing(indep_vars_long)) indep_vars_long <- jmvcore::resolveQuo(jmvcore::enquo(indep_vars_long))
    if ( ! missing(cov_long)) cov_long <- jmvcore::resolveQuo(jmvcore::enquo(cov_long))
    if ( ! missing(subject_id_var)) subject_id_var <- jmvcore::resolveQuo(jmvcore::enquo(subject_id_var))
    if ( ! missing(time_var)) time_var <- jmvcore::resolveQuo(jmvcore::enquo(time_var))
    if ( ! missing(wave_vars)) wave_vars <- jmvcore::resolveQuo(jmvcore::enquo(wave_vars))
    if ( ! missing(cat_var1)) cat_var1 <- jmvcore::resolveQuo(jmvcore::enquo(cat_var1))
    if ( ! missing(cat_var2)) cat_var2 <- jmvcore::resolveQuo(jmvcore::enquo(cat_var2))
    if (missing(data))
        data <- jmvcore::marshalData(
            parent.frame(),
            `if`( ! missing(dep_vars_cs), dep_vars_cs, NULL),
            `if`( ! missing(indep_vars_cs), indep_vars_cs, NULL),
            `if`( ! missing(cov), cov, NULL),
            `if`( ! missing(dep_vars_long), dep_vars_long, NULL),
            `if`( ! missing(indep_vars_long), indep_vars_long, NULL),
            `if`( ! missing(cov_long), cov_long, NULL),
            `if`( ! missing(subject_id_var), subject_id_var, NULL),
            `if`( ! missing(time_var), time_var, NULL),
            `if`( ! missing(wave_vars), wave_vars, NULL),
            `if`( ! missing(cat_var1), cat_var1, NULL),
            `if`( ! missing(cat_var2), cat_var2, NULL))


    options <- effectSizeOptions$new(
        mode = mode,
        dep_vars_cs = dep_vars_cs,
        indep_vars_cs = indep_vars_cs,
        cov = cov,
        dep_vars_long = dep_vars_long,
        indep_vars_long = indep_vars_long,
        cov_long = cov_long,
        subject_id_var = subject_id_var,
        time_var = time_var,
        wave_vars = wave_vars,
        long_format = long_format,
        include_interactions = include_interactions,
        run_analysis = run_analysis,
        es_method = es_method,
        show_cles = show_cles,
        reference_group = reference_group,
        es_method_long = es_method_long,
        show_cles_long = show_cles_long,
        reference_group_long = reference_group_long,
        use_glm = use_glm,
        es_glm = es_glm,
        ci_method = ci_method,
        n_bootstrap = n_bootstrap,
        ci_level = ci_level,
        show_conversions = show_conversions,
        benchmark_standard = benchmark_standard,
        show_es_plot = show_es_plot,
        plot_width = plot_width,
        plot_height = plot_height,
        show_categorical_es = show_categorical_es,
        cat_var1 = cat_var1,
        cat_var2 = cat_var2,
        calc_from_test_stat = calc_from_test_stat,
        stat_type = stat_type,
        stat_val = stat_val,
        stat_df1 = stat_df1,
        stat_df2 = stat_df2,
        stat_n = stat_n)

    analysis <- effectSizeClass$new(
        options = options,
        data = data)

    analysis$run()

    analysis$results
}

